mapper.select:
SELECT s.STORE_NO AS storeNo, s.STORE_NAME AS storeName, s.S_CATEGORY AS sCategory, s.S_ADDR AS sAddr, c.KOR AS sCategoryName, sd.SUB_TITLE AS subTitle, sf.FILE_PATH AS filePath, sf.FILE_NAME AS fileName FROM STORE s LEFT JOIN STORE_DETAIL sd ON s.STORE_NO = sd.STORE_NO LEFT JOIN CODE c ON s.S_CATEGORY = c.VALUE AND c.TYPE = 'S_CATEGORY' LEFT JOIN STORE_FILE sf ON s.STORE_NO = sf.STORE_NO AND sf.IS_MAIN = 'Y' LEFT JOIN USERS u ON u.USER_ID = #{sessionId} WHERE s.S_STATUS != 'EXT' AND s.S_CATEGORY = #{category} ORDER BY CASE WHEN #{sessionId} IS NOT NULL AND #{sessionId} != '' AND u.USER_ADDR IS NOT NULL AND u.USER_ADDR != '' AND s.S_ADDR IS NOT NULL AND s.S_ADDR != '' AND LEFT(TRIM(u.USER_ADDR), 2) = LEFT(TRIM(s.S_ADDR), 2) THEN 0 ELSE 1 END,
( SELECT COUNT(*) FROM RESERVATION r WHERE r.STORE_NO = s.STORE_NO ) DESC,
RAND() LIMIT 4;

SELECT p.PRODUCT_NO AS productNo, p.PRODUCT_NAME AS productName, p.PRODUCT_PRICE AS productPrice, pam.A_MAIN_NO AS aMainNo, pam.A_MAIN_TYPE AS aMainType, pf.FILE_PATH AS filePath, pf.FILE_NAME AS fileName, IFNULL(od.orderCnt, 0) AS orderCnt FROM PRODUCT p LEFT JOIN PC_ANIMAL_SUB pas ON pas.A_SUB_NO = p.A_SUB_NO LEFT JOIN PC_ANIMAL_MAIN pam ON pam.A_MAIN_NO = pas.A_MAIN_NO LEFT JOIN PRODUCT_FILE pf ON p.PRODUCT_NO = pf.PRODUCT_NO AND pf.IS_MAIN = 'Y' LEFT JOIN ( SELECT PRODUCT_NO, COUNT(*) AS orderCnt FROM ORDER_DETAIL GROUP BY PRODUCT_NO ) od ON p.PRODUCT_NO = od.PRODUCT_NO
WHERE pam.A_MAIN_NO = #{aMainNo} AND p.PRODUCT_STATUS = 'Y'
ORDER BY orderCnt DESC LIMIT 4;
